-- AutoERP portable legacy vehicle, customer, and current-ownership import
-- Source: deziutge_pos (15).sql / vehicles and referenced customers
-- Target schema: laravel (7).sql
-- Import organization code: AUTOERP; currency: LKR
-- Exact duplicate legacy vehicle rows are collapsed by normalized registration number.
-- Generated: 2026-08-21

SET NAMES utf8mb4;
SET time_zone = '+00:00';

DROP TEMPORARY TABLE IF EXISTS `_legacy_customers`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_customer_addresses`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_vehicle_makes`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_vehicle_models`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_vehicles`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_vehicle_ownerships`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_import_guard`;

CREATE TEMPORARY TABLE `_legacy_customers` (`legacy_id` bigint unsigned NOT NULL PRIMARY KEY, `code` varchar(191) NOT NULL UNIQUE, `name` varchar(191) NOT NULL, `legal_name` varchar(191) NULL, `email` varchar(191) NULL, `phone` varchar(191) NULL, `mobile` varchar(191) NULL, `tax_number` varchar(191) NULL, `status` varchar(30) NOT NULL, `created_at` timestamp NULL, `updated_at` timestamp NULL, `metadata` longtext NOT NULL);
CREATE TEMPORARY TABLE `_legacy_customer_addresses` (`legacy_customer_id` bigint unsigned NOT NULL PRIMARY KEY, `address_line_1` varchar(191) NOT NULL, `city` varchar(191) NULL, `state` varchar(191) NULL, `postal_code` varchar(191) NULL, `country` varchar(191) NULL, `created_at` timestamp NULL, `updated_at` timestamp NULL);
CREATE TEMPORARY TABLE `_legacy_vehicle_makes` (`code` varchar(191) NOT NULL PRIMARY KEY, `name` varchar(191) NOT NULL);
CREATE TEMPORARY TABLE `_legacy_vehicle_models` (`make_code` varchar(191) NOT NULL, `code` varchar(191) NOT NULL, `name` varchar(191) NOT NULL, PRIMARY KEY (`make_code`,`code`));
CREATE TEMPORARY TABLE `_legacy_vehicles` (`legacy_id` bigint unsigned NOT NULL PRIMARY KEY, `code` varchar(191) NOT NULL UNIQUE, `registration_number` varchar(191) NOT NULL UNIQUE, `make_code` varchar(191) NOT NULL, `model_code` varchar(191) NOT NULL, `fuel_type` varchar(30) NOT NULL, `created_at` timestamp NULL, `updated_at` timestamp NULL, `metadata` longtext NOT NULL);
CREATE TEMPORARY TABLE `_legacy_vehicle_ownerships` (`legacy_vehicle_id` bigint unsigned NOT NULL PRIMARY KEY, `legacy_customer_id` bigint unsigned NOT NULL, `started_at` datetime NOT NULL);
CREATE TEMPORARY TABLE `_legacy_import_guard` (`message` varchar(255) NOT NULL);













































START TRANSACTION;

SET @legacy_tenant_id := (SELECT `tenant_id` FROM `organization_units` WHERE `code` = 'AUTOERP' LIMIT 1);
SET @legacy_org_id := (SELECT `id` FROM `organization_units` WHERE `code` = 'AUTOERP' LIMIT 1);
SET @legacy_currency_id := (SELECT `id` FROM `currencies` WHERE `code` = 'LKR' LIMIT 1);

SELECT NULL WHERE (SELECT COUNT(*) FROM `organization_units` WHERE `code` = 'AUTOERP') <> 1;
SELECT NULL WHERE (SELECT COUNT(*) FROM `currencies` WHERE `code` = 'LKR') <> 1;
SELECT NULL WHERE EXISTS (
  SELECT 1 FROM `_legacy_customers` s JOIN `customers` c ON c.`tenant_id`=@legacy_tenant_id AND c.`customer_number`=s.`code` WHERE c.`code`<>s.`code`
);
SELECT NULL WHERE EXISTS (
  SELECT 1 FROM `_legacy_vehicles` s JOIN `vehicles` v ON v.`tenant_id`=@legacy_tenant_id AND (v.`vehicle_number`=s.`registration_number` OR v.`registration_number`=s.`registration_number`) WHERE v.`code`<>s.`code`
);

SELECT 1,@legacy_tenant_id,@legacy_org_id,s.`code`,s.`code`,s.`name`,s.`legal_name`,s.`name`,'retail',s.`status`,s.`email`,s.`phone`,s.`mobile`,NULL,@legacy_currency_id,NULL,s.`tax_number`,NULL,NULL,NULL,0,0,NULL,NULL,s.`metadata`,NULL,NULL,s.`created_at`,s.`updated_at`,NULL
FROM `_legacy_customers` s
ON DUPLICATE KEY UPDATE
  `row_version`=IF(`customers`.`name`<>VALUES(`name`) OR NOT (`customers`.`email`<=>VALUES(`email`)) OR NOT (`customers`.`phone`<=>VALUES(`phone`)) OR NOT (`customers`.`mobile`<=>VALUES(`mobile`)) OR `customers`.`status`<>VALUES(`status`),`customers`.`row_version`+1,`customers`.`row_version`),
  `organization_unit_id`=VALUES(`organization_unit_id`),`name`=VALUES(`name`),`legal_name`=VALUES(`legal_name`),`display_name`=VALUES(`display_name`),
  `customer_type`=VALUES(`customer_type`),`status`=VALUES(`status`),`email`=VALUES(`email`),`phone`=VALUES(`phone`),`mobile`=VALUES(`mobile`),
  `default_currency_id`=VALUES(`default_currency_id`),`tax_registration_number`=VALUES(`tax_registration_number`),`metadata`=VALUES(`metadata`),`updated_at`=VALUES(`updated_at`),`deleted_at`=NULL;

SELECT @legacy_tenant_id,@legacy_org_id,c.`id`,'registered',s.`address_line_1`,NULL,s.`city`,s.`state`,s.`postal_code`,s.`country`,1,1,s.`created_at`,s.`updated_at`,NULL
FROM `_legacy_customer_addresses` s
JOIN `_legacy_customers` sc ON sc.`legacy_id`=s.`legacy_customer_id`
JOIN `customers` c ON c.`tenant_id`=@legacy_tenant_id AND c.`code`=sc.`code`
WHERE NOT EXISTS (
  SELECT 1 FROM `customer_addresses` a WHERE a.`tenant_id`=@legacy_tenant_id AND a.`customer_id`=c.`id` AND a.`address_type`='registered'
    AND a.`address_line_1`=s.`address_line_1` AND (a.`city`<=>s.`city`) AND (a.`state`<=>s.`state`) AND (a.`postal_code`<=>s.`postal_code`) AND (a.`country`<=>s.`country`) AND a.`deleted_at` IS NULL
);

SELECT @legacy_tenant_id,@legacy_org_id,s.`code`,s.`name`,'Normalized from legacy vehicle data.',1,UTC_TIMESTAMP(),UTC_TIMESTAMP(),NULL
FROM `_legacy_vehicle_makes` s
WHERE NOT EXISTS (SELECT 1 FROM `vehicle_makes` m WHERE m.`tenant_id`=@legacy_tenant_id AND m.`code`=s.`code`);

SELECT @legacy_tenant_id,@legacy_org_id,m.`id`,s.`code`,s.`name`,NULL,NULL,'Normalized from legacy vehicle data.',1,UTC_TIMESTAMP(),UTC_TIMESTAMP(),NULL
FROM `_legacy_vehicle_models` s
JOIN `vehicle_makes` m ON m.`tenant_id`=@legacy_tenant_id AND m.`code`=s.`make_code`
WHERE NOT EXISTS (SELECT 1 FROM `vehicle_models` vm WHERE vm.`tenant_id`=@legacy_tenant_id AND vm.`vehicle_make_id`=m.`id` AND vm.`code`=s.`code`);

SELECT 1,@legacy_tenant_id,@legacy_org_id,s.`registration_number`,s.`code`,m.`id`,vm.`id`,NULL,NULL,s.`registration_number`,NULL,NULL,NULL,NULL,NULL,NULL,s.`fuel_type`,NULL,0.000000,'km',NULL,'active',NULL,s.`metadata`,NULL,NULL,s.`created_at`,s.`updated_at`,NULL
FROM `_legacy_vehicles` s
JOIN `vehicle_makes` m ON m.`tenant_id`=@legacy_tenant_id AND m.`code`=s.`make_code`
JOIN `vehicle_models` vm ON vm.`tenant_id`=@legacy_tenant_id AND vm.`vehicle_make_id`=m.`id` AND vm.`code`=s.`model_code`
ON DUPLICATE KEY UPDATE
  `row_version`=IF(`vehicles`.`vehicle_number`<>VALUES(`vehicle_number`) OR NOT (`vehicles`.`vehicle_make_id`<=>VALUES(`vehicle_make_id`)) OR NOT (`vehicles`.`vehicle_model_id`<=>VALUES(`vehicle_model_id`)) OR NOT (`vehicles`.`fuel_type`<=>VALUES(`fuel_type`)),`vehicles`.`row_version`+1,`vehicles`.`row_version`),
  `organization_unit_id`=VALUES(`organization_unit_id`),`vehicle_number`=VALUES(`vehicle_number`),`vehicle_make_id`=VALUES(`vehicle_make_id`),
  `vehicle_model_id`=VALUES(`vehicle_model_id`),`registration_number`=VALUES(`registration_number`),`fuel_type`=VALUES(`fuel_type`),
  `status`='active',`metadata`=VALUES(`metadata`),`updated_at`=VALUES(`updated_at`),`deleted_at`=NULL;

SELECT NULL FROM `_legacy_vehicle_ownerships` s
JOIN `_legacy_vehicles` sv ON sv.`legacy_id`=s.`legacy_vehicle_id`
JOIN `_legacy_customers` sc ON sc.`legacy_id`=s.`legacy_customer_id`
JOIN `vehicles` v ON v.`tenant_id`=@legacy_tenant_id AND v.`code`=sv.`code`
JOIN `customers` c ON c.`tenant_id`=@legacy_tenant_id AND c.`code`=sc.`code`
JOIN `vehicle_ownerships` o ON o.`tenant_id`=@legacy_tenant_id AND o.`vehicle_id`=v.`id` AND o.`owner_type`='customer' AND o.`is_current`=1
WHERE o.`owner_id`<>c.`id`;

SELECT 1,@legacy_tenant_id,@legacy_org_id,v.`id`,'customer',c.`id`,CONCAT('customer:',c.`id`),c.`code`,c.`name`,'customer_owned',s.`started_at`,NULL,1,1,1,'Imported current ownership from deziutge_pos (15).sql.',s.`started_at`,s.`started_at`
FROM `_legacy_vehicle_ownerships` s
JOIN `_legacy_vehicles` sv ON sv.`legacy_id`=s.`legacy_vehicle_id`
JOIN `_legacy_customers` sc ON sc.`legacy_id`=s.`legacy_customer_id`
JOIN `vehicles` v ON v.`tenant_id`=@legacy_tenant_id AND v.`code`=sv.`code`
JOIN `customers` c ON c.`tenant_id`=@legacy_tenant_id AND c.`code`=sc.`code`
WHERE NOT EXISTS (SELECT 1 FROM `vehicle_ownerships` o WHERE o.`tenant_id`=@legacy_tenant_id AND o.`vehicle_id`=v.`id` AND o.`owner_type`='customer' AND o.`is_current`=1);

COMMIT;

SELECT 'legacy_customers' AS `dataset`,COUNT(*) AS `imported_or_reconciled` FROM `customers` c JOIN `_legacy_customers` s ON s.`code`=c.`code` WHERE c.`tenant_id`=@legacy_tenant_id
UNION ALL SELECT 'legacy_customer_addresses',COUNT(*) FROM `customer_addresses` a JOIN `customers` c ON c.`id`=a.`customer_id` JOIN `_legacy_customers` s ON s.`code`=c.`code` WHERE a.`tenant_id`=@legacy_tenant_id AND a.`deleted_at` IS NULL
UNION ALL SELECT 'legacy_vehicles',COUNT(*) FROM `vehicles` v JOIN `_legacy_vehicles` s ON s.`code`=v.`code` WHERE v.`tenant_id`=@legacy_tenant_id
UNION ALL SELECT 'legacy_current_ownerships',COUNT(*) FROM `vehicle_ownerships` o JOIN `vehicles` v ON v.`id`=o.`vehicle_id` JOIN `_legacy_vehicles` s ON s.`code`=v.`code` WHERE o.`tenant_id`=@legacy_tenant_id AND o.`owner_type`='customer' AND o.`is_current`=1;

DROP TEMPORARY TABLE IF EXISTS `_legacy_customers`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_customer_addresses`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_vehicle_makes`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_vehicle_models`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_vehicles`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_vehicle_ownerships`;
DROP TEMPORARY TABLE IF EXISTS `_legacy_import_guard`;
